(async () => {
  const pages = figma.root.children;
  const result = {};

  for (const page of pages) {
    const pageData = [];
    function traverse(node, depth = 0) {
      if (depth > 6) return;
      if (node.type === 'TEXT') {
        pageData.push({ type: 'TEXT', name: node.name, characters: node.characters });
      } else if (node.type === 'FRAME' || node.type === 'COMPONENT' || node.type === 'COMPONENT_SET' || node.type === 'SECTION') {
        const item = { type: node.type, id: node.id, name: node.name, childrenCount: node.children ? node.children.length : 0 };
        if (node.type === 'TEXT') item.characters = node.characters;
        pageData.push(item);
      }
      if ('children' in node) {
        for (const child of node.children) {
          traverse(child, depth + 1);
        }
      }
    }
    traverse(page);
    result[page.name + ' (' + page.id + ')'] = pageData;
  }
  return JSON.stringify(result, null, 2);
})();

