(async () => {
  // Let's get media assets from 04 · Media (1:4)
  const page = await figma.getNodeByIdAsync("1:4");
  const mediaList = [];
  function traverse(node) {
    if (node.type === 'COMPONENT' || node.type === 'FRAME' || node.type === 'INSTANCE' || node.type === 'GROUP' || node.type === 'VECTOR') {
      if (node.name.startsWith('Icon_') || node.name.startsWith('Product_') || node.name.startsWith('Category_') || node.name.startsWith('Banner_') || node.name.startsWith('Photo_') || node.name.startsWith('Illustration_') || node.name.startsWith('Flag_') || node.name.startsWith('Logo_') || node.name.startsWith('Avatar_') || node.name.startsWith('Nectar_')) {
        mediaList.push({ id: node.id, name: node.name, type: node.type, parent: node.parent ? node.parent.name : null });
      }
    }
    if ('children' in node) {
      for (const child of node.children) {
        traverse(child);
      }
    }
  }
  traverse(page);
  return mediaList;
})();

