(async () => {
  const workspace = await figma.getNodeByIdAsync("7:2");
  await figma.setCurrentPageAsync(workspace);

  // Load fonts
  await figma.loadFontAsync({ family: "Poppins", style: "Regular" });
  await figma.loadFontAsync({ family: "Poppins", style: "Medium" });
  await figma.loadFontAsync({ family: "Poppins", style: "Semi Bold" });
  await figma.loadFontAsync({ family: "Poppins", style: "Bold" });

  const compSection = figma.currentPage.findOne(n => n.name === "Reusable Components");

  // Let's create the Main Navigation (TabBar) component
  let tabBarComp = compSection.findOne(n => n.name === "TabBar" && n.type === "COMPONENT_SET");
  if (!tabBarComp) {
    // We will build it as variants, but to keep it simple, we can build separate components for each active tab
    // Or a single component with variants: Tab=Shop, Tab=Explore, Tab=Cart, Tab=Account
    // Let's build a component set!

    // First let's create components for each tab state, then combine them
    const createTabVariant = (activeTab) => {
      const v = figma.createComponent();
      v.name = `Tab=${activeTab}`;
      v.resize(414, 85); // 414 wide, 85 high (reaches bottom with safe area)
      v.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
      v.effects = [{
        type: 'DROP_SHADOW',
        color: { r: 0, g: 0, b: 0, a: 0.05 },
        offset: { x: 0, y: -4 },
        radius: 12,
        visible: true,
        blendMode: 'NORMAL'
      }];

      // 5 Tabs: Shop, Explore, Cart, Favourite, Account
      const tabs = [
        { name: 'Shop', icon: 'Icon_Shop' },
        { name: 'Explore', icon: 'Icon_Explore' },
        { name: 'Cart', icon: 'Icon_Cart' },
        { name: 'Favourite', icon: 'Icon_Favourite' },
        { name: 'Account', icon: 'Icon_Account' }
      ];

      const tabWidth = 414 / 5;
      tabs.forEach((tab, index) => {
        const isActive = tab.name === activeTab;
        const x = index * tabWidth;

        // Container frame for the tab item to handle interactions easily
        const tabItem = figma.createFrame();
        tabItem.name = `TabItem_${tab.name}`;
        tabItem.resize(tabWidth, 65);
        tabItem.x = x;
        tabItem.y = 0;
        tabItem.fills = [];
        v.appendChild(tabItem);

        // Text label
        const txt = figma.createText();
        txt.name = "Label";
        txt.fontName = { family: "Poppins", style: "Semi Bold" };
        txt.fontSize = 12;
        txt.characters = tab.name;
        txt.fills = [{ type: 'SOLID', color: isActive ? { r: 0.325, g: 0.694, b: 0.459 } : { r: 0.102, g: 0.125, b: 0.173 } }];
        txt.textAlignHorizontal = "CENTER";
        txt.resize(tabWidth, 18);
        txt.x = 0;
        txt.y = 42;
        tabItem.appendChild(txt);

        // Icon placeholder - we will copy the actual vector paths during frame creation or instantiate instances
        const iconFrame = figma.createFrame();
        iconFrame.name = `IconContainer`;
        iconFrame.resize(24, 24);
        iconFrame.x = (tabWidth - 24) / 2;
        iconFrame.y = 12;
        iconFrame.fills = [];
        tabItem.appendChild(iconFrame);
      });

      return v;
    };

    const vShop = createTabVariant('Shop');
    const vExplore = createTabVariant('Explore');
    const vCart = createTabVariant('Cart');
    const vAccount = createTabVariant('Account');

    vShop.x = 0; vShop.y = 300;
    vExplore.x = 450; vExplore.y = 300;
    vCart.x = 0; vCart.y = 420;
    vAccount.x = 450; vAccount.y = 420;

    compSection.appendChild(vShop);
    compSection.appendChild(vExplore);
    compSection.appendChild(vCart);
    compSection.appendChild(vAccount);

    // Let's also create empty variants or define component names
    vShop.name = "TabBar_Shop";
    vExplore.name = "TabBar_Explore";
    vCart.name = "TabBar_Cart";
    vAccount.name = "TabBar_Account";
  }

  return "TabBar components created for Shop, Explore, Cart, Account.";
})();

