(async () => {
  const workspace = await figma.getNodeByIdAsync("7:2");
  await figma.setCurrentPageAsync(workspace);

  // Helper function to find node by name inside a parent
  function findNodeByName(parent, name) {
    let result = null;
    function traverse(n) {
      if (n.name === name) {
        result = n;
        return;
      }
      if ('children' in n) {
        for (const child of n.children) {
          if (!result) traverse(child);
        }
      }
    }
    traverse(parent);
    return result;
  }

  // Get all 12 frames
  const f01 = workspace.children.find(c => c.name === "01_Splash");
  const f02 = workspace.children.find(c => c.name === "02_Onboarding");
  const f03 = workspace.children.find(c => c.name === "03_Sign_In");
  const f04 = workspace.children.find(c => c.name === "04_Verification");
  const f05 = workspace.children.find(c => c.name === "05_Home");
  const f06 = workspace.children.find(c => c.name === "06_Product_Detail");
  const f07 = workspace.children.find(c => c.name === "07_Explore");
  const f08 = workspace.children.find(c => c.name === "08_Beverages");
  const f09 = workspace.children.find(c => c.name === "09_My_Cart");
  const f10 = workspace.children.find(c => c.name === "10_Checkout_Overlay");
  const f11 = workspace.children.find(c => c.name === "11_Order_Accepted");
  const f12 = workspace.children.find(c => c.name === "12_Account");

  // Helper for adding prototype reaction
  function setTapReaction(sourceNode, destinationFrame) {
    if (!sourceNode || !destinationFrame) return;
    sourceNode.reactions = [{
      action: {
        type: "NODE",
        destinationId: destinationFrame.id,
        navigation: "NAVIGATE",
        transition: null
      },
      trigger: { type: "ON_CLICK" }
    }];
  }

  // Helper to wire TabBar links on a screen
  function wireTabBar(screenFrame, currentTabName) {
    if (!screenFrame) return;
    const shopTab = findNodeByName(screenFrame, "TabItem_Shop");
    const exploreTab = findNodeByName(screenFrame, "TabItem_Explore");
    const cartTab = findNodeByName(screenFrame, "TabItem_Cart");
    const accountTab = findNodeByName(screenFrame, "TabItem_Account");

    if (currentTabName !== "Shop") setTapReaction(shopTab, f05);
    if (currentTabName !== "Explore") setTapReaction(exploreTab, f07);
    if (currentTabName !== "Cart") setTapReaction(cartTab, f09);
    if (currentTabName !== "Account") setTapReaction(accountTab, f12);
  }

  // 1. Onboarding flow
  // 01_Splash -> auto or click -> 02_Onboarding
  setTapReaction(f01, f02);

  // 02_Onboarding -> Get Started -> 03_Sign_In
  const getStartedBtn = findNodeByName(f02, "Button");
  setTapReaction(getStartedBtn, f03);

  // 03_Sign_In -> phone number area -> 04_Verification
  const phoneInput = findNodeByName(f03, "PhoneInput");
  setTapReaction(phoneInput, f04);

  // 04_Verification -> back -> 03_Sign_In
  const back04 = findNodeByName(f04, "BackBtn");
  setTapReaction(back04, f03);

  // 04_Verification -> next -> 05_Home
  const nextFab = findNodeByName(f04, "NextFAB");
  setTapReaction(nextFab, f05);

  // 2. 05_Home links
  wireTabBar(f05, "Shop");
  // Red Apple -> 06_Product_Detail
  const redAppleCard = findNodeByName(f05, "ProductCard_Red Apple");
  setTapReaction(redAppleCard, f06);

  // 3. 06_Product_Detail links
  // back -> 05_Home
  const back06 = findNodeByName(f06, "BackBtn");
  setTapReaction(back06, f05);
  // Add To Basket -> 09_My_Cart
  const addToBasketBtn = findNodeByName(f06, "Button");
  setTapReaction(addToBasketBtn, f09);

  // 4. 07_Explore links
  wireTabBar(f07, "Explore");
  // Beverages category card -> 08_Beverages
  const bevCatCard = findNodeByName(f07, "CategoryCard_Beverages");
  setTapReaction(bevCatCard, f08);

  // 5. 08_Beverages links
  // back -> 07_Explore
  const back08 = findNodeByName(f08, "BackBtn");
  setTapReaction(back08, f07);

  // 6. 09_My_Cart links
  wireTabBar(f09, "Cart");
  // Go to Checkout -> 10_Checkout_Overlay
  const checkoutBtn = findNodeByName(f09, "GoToCheckoutBtn");
  setTapReaction(checkoutBtn, f10);

  // 7. 10_Checkout_Overlay links
  // close -> 09_My_Cart
  const close10 = findNodeByName(f10, "CloseBtn");
  setTapReaction(close10, f09);
  // Place Order -> 11_Order_Accepted
  const placeOrderBtn = findNodeByName(f10, "Button");
  setTapReaction(placeOrderBtn, f11);

  // 8. 11_Order_Accepted links
  // Back to home -> 05_Home
  const backToHome11 = findNodeByName(f11, "BackToHomeBtn");
  setTapReaction(backToHome11, f05);

  // 9. 12_Account links
  wireTabBar(f12, "Account");

  return "Clickable prototype interactions wired successfully across all 12 screens!";
})();

