  setTapReaction(addToBasketBtn, f09);

  // 4. 07_Explore links
  wireTabBar(f07, "Explore");
  const bevCatCard = findNodeByName(f07, "CategoryCard_Beverages");
  setTapReaction(bevCatCard, f08);

  // 5. 08_Beverages links
  const back08 = findNodeByName(f08, "BackBtn");
  setTapReaction(back08, f07);

  // 6. 09_My_Cart links
  wireTabBar(f09, "Cart");
  const checkoutBtn = findNodeByName(f09, "GoToCheckoutBtn");
  setTapReaction(checkoutBtn, f10);

  // 7. 10_Checkout_Overlay links
  const close10 = findNodeByName(f10, "CloseBtn");
  setTapReaction(close10, f09);
